package com.badrulamin.University_Management.repository;  import com.badrulamin.University_Management.entity.ApplicationReview; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.stereotype.Repository;  import java.util.List;  @Repository public interface ApplicationReviewRepository extends JpaRepository<ApplicationReview, Long> {     Page<ApplicationReview> findByStatus(String status, Pageable pageable);     List<ApplicationReview> findByApplication_Id(Long applicationId);     List<ApplicationReview> findByReviewer_Id(Long reviewerId);     long countByStatus(String status); }